/** Actual pick input uses private registered production classes, including hidden imported chip ownership. */
@EventBusSubscriber(modid="vandorlabs")
public final class ScreenPickClientFixture {
 static final BlockPos ROOT=new BlockPos(0,96,0),ACK=ROOT.east(3);static final String MARKER="screen-private-pick-import";static final java.util.Map<ScreenFamily,NativeScreenBlock> BLOCKS=new java.util.EnumMap<>(ScreenFamily.class);static BlockEntityType<NativeScreenEntity> TYPE;private static java.util.UUID actorId;private static int step,checks;
 public static boolean enabled(){return "screen-pick-client".equals(System.getProperty("vandorlabs.transmitterPhase"));}
 public record Ack(int step) implements CustomPacketPayload{static final Type<Ack> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:screen_pick_client_ack"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(var family:ScreenFamily.values()){var block=NativeScreenBlock.create(family,BlockBehaviour.Properties.of(),()->TYPE);BLOCKS.put(family,block);h.register(ResourceLocation.parse("vandorlabs:screen_pick_client_"+family.ordinal()),block);}});event.register(Registries.ITEM,h->{for(var entry:BLOCKS.entrySet())h.register(ResourceLocation.parse("vandorlabs:screen_pick_client_"+entry.getKey().ordinal()),new NativeScreenItem(entry.getValue(),new Item.Properties()));});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeScreenEntity>of((p,s)->new NativeScreenEntity(TYPE,p,s,((NativeScreenBlock)s.getBlock()).family(),NativeScreenCatalog.INSTANCE),BLOCKS.values().toArray(Block[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:screen_pick_client"),TYPE);});}
  @SubscribeEvent public static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;ScreenPickPayload.register(event);event.registrar("1").playToServer(Ack.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Ack>(){public Ack decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException("Pick fixture ack length");int step=b.readUnsignedByte();if(step>=49)throw new IllegalArgumentException("Pick fixture ack step");return new Ack(step);}public void encode(RegistryFriendlyByteBuf b,Ack p){b.writeByte(p.step);}},(p,c)->c.enqueueWork(()->{if(c.player() instanceof ServerPlayer player)ack(player,p.step);}));}
 }
 private static void need(boolean value,String reason){checks++;if(!value)throw new AssertionError("Screen pick server step="+step+": "+reason);}
 static CompoundTag imported(){var item=new CompoundTag();item.putString("id","vandorlabs:data_chip");item.putByte("Count",(byte)64);item.putShort("Damage",(short)2);item.putString("OpaqueImportMarker",MARKER);var tag=new CompoundTag();tag.putString("ChipType","journal");tag.putString("JournalTitle","Private saved chip");var pages=new ListTag();pages.add(StringTag.valueOf("Private journal preserved by configured pick"));tag.put("JournalPages",pages);item.put("tag",tag);var caps=new CompoundTag();caps.putString("foreign:chip",MARKER);item.put("ForgeCaps",caps);return item;}
 private static NativeScreenEntity owner(ServerPlayer player){return (NativeScreenEntity)player.serverLevel().getBlockEntity(ROOT);}
 static boolean creative(int step){return step<28;}static int role(int step){return step<28?step/4:(step-28)/3;}static int scenario(int step){return step<28?step%4:1+(step-28)%3;}
 private static java.util.List<ItemStack> survivalBefore;
 static int initialSlot(int scenario){return new int[]{4,2,3,5}[scenario];}static int selectedSlot(int scenario){return new int[]{4,7,6,5}[scenario];}static int pickedCount(int scenario){return new int[]{1,3,2,1}[scenario];}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer player))return;actorId=player.getUUID();var world=player.serverLevel();world.getChunkAt(ROOT);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){world.setBlock(new BlockPos(x,95,z),Blocks.STONE.defaultBlockState(),3);for(int y=96;y<=100;y++)world.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}setup(player);System.out.println("[vandorlabs][screen-pick-client] setup PASS");}
 private static void setup(ServerPlayer player){var world=player.serverLevel();var family=ScreenFamily.values()[role(step)];int scenario=scenario(step);world.setBlock(ROOT,Blocks.AIR.defaultBlockState(),3);world.setBlock(ROOT,BLOCKS.get(family).defaultBlockState(),3);var tile=owner(player);var raw=new CompoundTag();var reader=new CompoundTag();reader.put("InsertedToken",imported());raw.put("ScreenChipReader",reader);raw.putString("PrivatePickRoot",MARKER);tile.loadWithComponents(raw,world.registryAccess());tile.onLoad();NativeRedstoneChannels.flush(world);need(!tile.inert(),"hidden reader accepted");need(!tile.getUpdateTag(world.registryAccess()).toString().contains(MARKER)&&!tile.getUpdateTag(world.registryAccess()).contains("ScreenChipReader"),"normal update DTO excludes physical/import snapshot");
 player.setGameMode(creative(step)?GameType.CREATIVE:GameType.SURVIVAL);var inventory=player.getInventory();inventory.clearContent();inventory.selected=step==0?0:initialSlot(scenario);var expected=NativeScreenItemSettings.pick(BLOCKS.get(family).asItem(),tile,world.registryAccess());switch(scenario){case 0->inventory.setItem(0,new ItemStack(Items.STONE,7));case 1->inventory.setItem(7,expected.copyWithCount(3));case 2->{for(int i=0;i<9;i++)inventory.setItem(i,new ItemStack(Items.DIRT,i+1));inventory.setItem(3,new ItemStack(Items.STONE,11));inventory.setItem(6,ItemStack.EMPTY);inventory.setItem(12,expected.copyWithCount(2));}case 3->{for(int i=0;i<9;i++)inventory.setItem(i,new ItemStack(Items.DIRT,i+1));}}
 survivalBefore=inventory.items.stream().map(ItemStack::copy).toList();player.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);var bounds=BLOCKS.get(family).geometry(tile.getBlockState(),world,ROOT).bounds();double tx=ROOT.getX()+(bounds.minX+bounds.maxX)/2,ty=ROOT.getY()+(bounds.minY+bounds.maxY)/2,tz=ROOT.getZ()+(bounds.minZ+bounds.maxZ)/2;double x=.5,y=96,z=-3,dx=tx-x,dy=ty-(y+player.getEyeHeight()),dz=tz-z;player.getAbilities().flying=true;player.onUpdateAbilities();player.connection.teleport(x,y,z,(float)-Math.toDegrees(Math.atan2(dx,dz))+(step==0?180:0),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz))));player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(inventory.selected));inventory.setChanged();player.inventoryMenu.broadcastChanges();System.out.println("[vandorlabs][screen-pick-client] ready step="+step+" selected="+inventory.selected+" state="+player.inventoryMenu.getStateId());}
 static void verify(ItemStack stack,HolderLookup.Provider registries){var settings=NativeScreenItemSettings.configuration(stack);need(settings!=null&&settings.getString("PrivatePickRoot").equals(MARKER),"full server-only root snapshot in item");var chip=NativeCredentialItems.readStack(settings.getCompound("ScreenChipReader").getCompound("InsertedToken"),registries);need(chip.getCount()==1&&NativeCredentialItems.company(chip)==2&&NativeCredentialItems.legacyCredentialData(chip).equals(imported()),"one complete chip and opaque original tag/capabilities");}
 private static void rejects(ServerPlayer player){var inventory=player.getInventory();int selected=inventory.selected,state=player.inventoryMenu.getStateId();var before=inventory.items.stream().map(ItemStack::copy).toList();var position=player.position();float yaw=player.getYRot();var current=new ScreenPickPayload(ROOT,selected,state);need(!new ScreenPickPayload(ROOT,(selected+1)%9,state).apply(player),"wrong selected context refused");need(!new ScreenPickPayload(ROOT,selected,(state+1)&32767).apply(player),"stale inventory state refused");need(!new ScreenPickPayload(ROOT.east(4),selected,state).apply(player),"wrong looked-at owner refused");var menu=player.containerMenu;try{player.containerMenu=new NativeScreenMenu(null,91,owner(player));need(!current.apply(player),"open foreign container refused");}finally{player.containerMenu=menu;}player.inventoryMenu.setCarried(new ItemStack(Items.DIRT));try{need(!current.apply(player),"carried inventory cursor refused");}finally{player.inventoryMenu.setCarried(ItemStack.EMPTY);}var owned=inventory.getItem(selected);inventory.setItem(selected,ItemStack.EMPTY);player.setGameMode(GameType.SURVIVAL);try{need(!current.apply(player),"survival without existing match cannot mint configured private item");}finally{player.setGameMode(GameType.CREATIVE);inventory.setItem(selected,owned);}player.setPos(position.add(0,0,-20));try{need(!current.apply(player),"current reach recomputed");}finally{player.setPos(position);}player.setYRot(yaw+180);try{need(!current.apply(player),"current look recomputed");}finally{player.setYRot(yaw);}var level=player.serverLevel();int loaded=level.getChunkSource().getLoadedChunksCount();need(!new ScreenPickPayload(ROOT.offset(160000,0,160000),selected,state).apply(player)&&level.getChunkSource().getLoadedChunksCount()==loaded,"unloaded request cannot force chunks");for(int y=0;y<2;y++)level.setBlock(ROOT.north().above(y),Blocks.STONE.defaultBlockState(),3);try{need(!current.apply(player),"nearer terrain refuses forged target");}finally{for(int y=0;y<2;y++)level.setBlock(ROOT.north().above(y),Blocks.AIR.defaultBlockState(),3);}var stand=new net.minecraft.world.entity.decoration.ArmorStand(level,.5,96,-1.5);stand.setNoGravity(true);level.addFreshEntity(stand);try{need(!current.apply(player),"nearer pickable entity refuses forged target");}finally{stand.discard();}need(inventory.selected==selected,"refusals preserve hotbar selection");for(int index=0;index<before.size();index++)need(ItemStack.matches(before.get(index),inventory.items.get(index)),"refusals preserve inventory slot "+index);}
 private static void ack(ServerPlayer player,int received){need(player.getUUID().equals(actorId)&&step==received&&player.isCreative()==creative(step)&&player.containerMenu==player.inventoryMenu,"current actor/inventory context");int scenario=scenario(step);var inventory=player.getInventory();boolean absent=!creative(step)&&scenario==3;need(inventory.selected==selectedSlot(scenario)&&player.getMainHandItem().getCount()==(absent?6:pickedCount(scenario)),"vanilla hotbar slot/count selection");if(absent)need(player.getMainHandItem().is(Items.DIRT),"absent survival match leaves held item unchanged");else verify(player.getMainHandItem(),player.registryAccess());if(!creative(step)){need(survivalBefore.stream().mapToInt(ItemStack::getCount).sum()==inventory.items.stream().mapToInt(ItemStack::getCount).sum(),"survival total count preserved");for(var prior:survivalBefore)if(!prior.isEmpty()){int beforeCount=survivalBefore.stream().filter(item->ItemStack.isSameItemSameComponents(item,prior)).mapToInt(ItemStack::getCount).sum(),afterCount=inventory.items.stream().filter(item->ItemStack.isSameItemSameComponents(item,prior)).mapToInt(ItemStack::getCount).sum();need(beforeCount==afterCount,"survival complete component/count multiset preserved");}}verify(NativeScreenItemSettings.pick(BLOCKS.get(owner(player).family()).asItem(),owner(player),player.registryAccess()),player.registryAccess());if(scenario==0)need(inventory.getItem(0).is(Items.STONE)&&inventory.getItem(0).getCount()==7,"empty-slot pick preserves other inventory");if(scenario==2)need(inventory.getItem(12).isEmpty()&&inventory.getItem(3).is(Items.STONE)&&inventory.getItem(3).getCount()==11,"storage swap preserves old selected stack");if(scenario==3&&creative(step))need(inventory.getItem(9).is(Items.DIRT)&&inventory.getItem(9).getCount()==6,"replacement saves displaced hotbar stack");if(step==0)rejects(player);System.out.println("[vandorlabs][screen-pick-client] pick PASS step="+step);step++;if(step<49)setup(player);else player.serverLevel().setBlock(ACK,Blocks.STONE.defaultBlockState(),3);}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()&&event.getEntity().getUUID().equals(actorId)){need(step==49,"all seven roles/creative and survival inventory cases completed");System.out.println("[vandorlabs][screen-pick-client] logout PASS checks="+checks);}}
}
